                  as="button"
                  onClick={() => {
                    stopGenerateRef.current = true; // Clicking this button stops generating text
                  }}
                >
                  <div className="flex w-full gap-2 items-center justify-center">
                    <svg
                      stroke="currentColor"
                      fill="none"
                      strokeWidth="2"
                      viewBox="0 0 24 24"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      className="icon-xs"
