                    >
                      <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
                    </svg>
                    Stop Generating
                  </div>
                </button>
              </div>
            </div>
          </div>
        </div>
        <form id="input-form" onSubmit={handleSubmit}>
          <div className="message-container bg-white rounded-3xl shadow">
            <textarea
              id="input-field"
              ref={inputRef}
