here is my unity code which connects too the python server

using UnityEngine;
using UnityEngine.UI;
using System.Collections;
using System.Diagnostics;
using System.Net.Sockets;
using System.Text;
using System;

public class ChatGPTWithEyes : MonoBehaviour
{
    public Camera object1Camera;
    public Camera object2Camera;
    public Text chatText;

    private bool isWaitingForResponse = false;
    private TcpClient client;
    private NetworkStream stream;

    private void Start()
    {
        // Connect to the Python server
        ConnectToServer();
    }

    private void ConnectToServer()
    {
        // Create a TCP client and connect to the server
        client = new TcpClient("localhost", 9999);
        stream = client.GetStream();

        // Start receiving messages from the server in a separate thread
        StartReceivingMessages();
    }

    private void StartReceivingMessages()
    {
        byte[] buffer = new byte[1024];

        // Begin receiving messages from the server
        stream.BeginRead(buffer, 0, buffer.Length, ReceiveMessageCallback, buffer);
    }

    private void ReceiveMessageCallback(IAsyncResult ar)
    {
        byte[] buffer = (byte[])ar.AsyncState;
        int bytesRead = stream.EndRead(ar);

        if (bytesRead > 0)
        {
            // Convert the received data to a string
            string message = Encoding.ASCII.GetString(buffer, 0, bytesRead);

            // Display the received message in the chat text UI
            chatText.text = message;

            // Continue receiving messages from the server
            stream.BeginRead(buffer, 0, buffer.Length, ReceiveMessageCallback, buffer);
        }
        else
        {
            // The server has disconnected, clean up resources
            stream.Close();
            client.Close();
        }
    }

    private void LateUpdate()
    {
        // Only capture and send screenshots if not waiting for a response from the server
        if (!isWaitingForResponse)
        {
            // Capture screenshots of game view from the two objects
            Texture2D object1Screenshot = CaptureScreenshot(object1Camera);
            Texture2D object2Screenshot = CaptureScreenshot(object2Camera);

            // Convert screenshots to custom format strings
            string object1CustomFormat = ConvertToCustomFormat(object1Screenshot);
            string object2CustomFormat = ConvertToCustomFormat(object2Screenshot);

            // Send screenshots to the Python server for processing
            SendMessageToServer(object1CustomFormat, object2CustomFormat);
        }
    }

    private Texture2D CaptureScreenshot(Camera camera)
    {
        RenderTexture currentRT = RenderTexture.active;
        RenderTexture renderTexture = new RenderTexture(Screen.width, Screen.height, 24);
        camera.targetTexture = renderTexture;
        camera.Render();

        RenderTexture.active = renderTexture;
        Texture2D screenshot = new Texture2D(Screen.width, Screen.height, TextureFormat.RGB24, false);
        screenshot.ReadPixels(new Rect(0, 0, Screen.width, Screen.height), 0, 0);
        screenshot.Apply();

        camera.targetTexture = null;
        RenderTexture.active = currentRT;

        return screenshot;
    }

    private string ConvertToCustomFormat(Texture2D texture)
{
    StringBuilder customFormat = new StringBuilder();

    for (int y = 0; y < texture.height; y++)
    {
        for (int x = 0; x < texture.width; x++)
        {
            // Get the color of the pixel at (x, y)
            Color pixelColor = texture.GetPixel(x, y);

            // Encode the pixel color and position in the custom format
            string encodedColor = EncodeColor(pixelColor);
            string encodedPosition = EncodePosition(x, y);

            // Append the encoded color and position to the custom format string
            customFormat.Append("(");
            customFormat.Append(encodedPosition);
            customFormat.Append(")");
            customFormat.Append(encodedColor);
            customFormat.Append(" ");
        }
    }

    // Return the final custom format string
    return customFormat.ToString();
}

private string EncodeColor(Color color)
{
    // Convert the color to RGB values (0-255)
    int r = (int)(color.r * 255);
    int g = (int)(color.g * 255);
    int b = (int)(color.b * 255);

    // Encode the RGB values as a string
    string encodedColor = string.Format("{0},{1},{2}", r, g, b);

    return encodedColor;
}

private string EncodePosition(int x, int y)
{
    // Encode the position as a string
    string encodedPosition = string.Format("{0},{1}", x, y);

    return encodedPosition;
}


    private void SendMessageToServer(string object1CustomFormat, string object2CustomFormat)
    {
        string message = $"object1_custom_format:{object1CustomFormat}
object2_custom_format:{object2CustomFormat}";

        // Convert the message to bytes and send it to the server
        byte[] data = Encoding.ASCII.GetBytes(message);
        stream.Write(data, 0, data.Length);

        // Mark as waiting for a response from the server
        isWaitingForResponse = true;
    }
}

