    for file_name in file_names:
        file_path = os.path.join(directory_path, file_name)
        loader = PyPDFLoader(file_path)
        pages.extend(loader.load_and_split())
    return pages

def create_chroma_db(pages):
    return Chroma.from_documents(pages, collection_name='rapport')

def create_vectorstore_info(store):
    return VectorStoreInfo(name="rapport", description="rapport", vectorstore=store)

def create_toolkit_and_agent(vectorstore_info):
    toolkit = VectorStoreToolkit(vectorstore_info=vectorstore_info)
    return toolkit, create_vectorstore_agent(llm=llm, toolkit=toolkit, verbose=True)

# Initial setup
pages = load_pages_from_files()
store = create_chroma_db(pages)
vectorstore_info = create_vectorstore_info(store)
toolkit, agent_executor = create_toolkit_and_agent(vectorstore_info)

# Define a function to handle the API request with retries
@tenacity.retry(wait=tenacity.wait_random_exponential(multiplier=1, max=10), stop=tenacity.stop_after_attempt(5))
def process_prompt_with_retry(prompt):
    response = agent_executor.run(prompt, language='fr')  # Set the language parameter to 'fr' for French
    return response

# Route handler for the OPTIONS request
@app.route('/process_prompt', methods=['OPTIONS'])
@cross_origin()
def process_prompt_options():
    response = make_response()
    response.headers.add('Access-Control-Allow-Headers', 'Content-Type')
    response.headers.add('Access-Control-Allow-Methods', 'POST')
    return response

# Route handler for the POST request
@app.route('/process_prompt', methods=['POST'])
@cross_origin()
def process_prompt():
    prompt = request.json.get('prompt')
    if not prompt:
        return make_response(jsonify({"error": "No prompt provided"}), 400)

    try:
        with lock:
            response = process_prompt_with_retry(prompt)
        return jsonify(response)
    except tenacity.RetryError:
        return make_response(jsonify({"error": "API rate limit exceeded"}), 429)

@app.route('/register', methods=['POST'])
def register():
    username = request.json.get('username')
    email = request.json.get('email')
    password = request.json.get('password')

    if not username or not email or not password:
        return make_response(jsonify({"error": "Please provide username, email, and password"}), 400)

    hashed_password = bcrypt.generate_password_hash(password).decode('utf-8')
    new_user = User(username=username, email=email, password=hashed_password)
    db.session.add(new_user)
    db.session.commit()

    return jsonify({"message": "User registered successfully"}), 201

@app.route('/login', methods=['POST'])
def login():
    email = request.json.get('email')
    password = request.json.get('password')

    user = User.query.filter_by(email=email).first()

    if not user or not bcrypt.check_password_hash(user.password, password):
        return make_response(jsonify({"error": "Invalid email or password"}), 401)

    access_token = create_access_token(identity=user.id)
    return jsonify({"access_token": access_token}), 200

@app.route('/protected', methods=['GET'])
@jwt_required()
def protected():
    current_user = get_jwt_identity()
    return jsonify({"user_id": current_user}), 200

@app.route('/users', methods=['GET'])
def get_users():
    users = User.query.all()
    user_list = []
    for user in users:
        user_data = {
            'id': user.id,
            'username': user.username,
            'email': user.email
        }
        user_list.append(user_data)
    return jsonify(user_list)

@app.route('/users/<user_id>', methods=['DELETE'])
def delete_user(user_id):
    user = User.query.get(user_id)
    if not user:
        return make_response(jsonify({"error": "User not found"}), 404)

    db.session.delete(user)
    db.session.commit()
    return jsonify({"message": "User deleted successfully"}), 200

def update_chroma_db():
    global store, vectorstore_info, toolkit, agent_executor
    while True:
        pages = load_pages_from_files()
        store = create_chroma_db(pages)
        vectorstore_info.vectorstore = store
        toolkit, agent_executor = create_toolkit_and_agent(vectorstore_info)
        time.sleep(300)

if __name__ == '__main__':
    # Start the update function in a new thread
    update_thread = Thread(target=update_chroma_db)
    update_thread.start()

    # Start the Flask app
    app.run()


