GPT-4 & LangChain Tutorial: How to Chat with A 56-Pages of PDF
import { Request, Response } from "express";
import asyncHandler from 'express-async-handler';
import { v4 as uuidv4 } from 'uuid';
import { MarkdownTextSplitter } from "langchain/text_splitter";
import { PineconeClient } from '@pinecone-database/pinecone';
import { OpenAIEmbeddings } from 'langchain/embeddings/openai';
import { ChatOpenAI } from "langchain/chat_models/openai";
import { PineconeStore } from 'langchain/vectorstores/pinecone';
import { HumanChatMessage, SystemChatMessage } from "langchain/schema";
import { PromptTemplate } from "langchain";

/**
 * @method POST
 * @params role: rold ID, docText: Document Content, model: Embedding Model
 * @description Splite Markdown&HTML Document and generate embeddings from OpenAI
 */
export const generateEmbeddings = asyncHandler(
  async (req: Request, res: Response) => {
    const role: string = req.body.role as string;
    const docText: string = req.body.docText as string;
    // Get Unique id for document
    const documentId: string = uuidv4();

    const pinecone = new PineconeClient();
    const pineconeAPIKey: string = process.env.PINECONE_API_KEY ?? '';
    await pinecone.init({
      environment: process.env.PINECONE_ENVIRONMENT ?? '',
      apiKey: pineconeAPIKey,
    });

    try {
      const splitter = new MarkdownTextSplitter();

      const output = await splitter.createDocuments([docText], [{
        doc: documentId,
        role: role
      }]);

      console.log('creating vector store...');
      // Create and store the embeddings in the vectorStore
      const embeddings = new OpenAIEmbeddings();
      const index = pinecone.Index(process.env.PINECONE_INDEX ?? '');
      const dbConfig = {
        pineconeIndex: index,
        namespace: process.env.PINECONE_NAMESPACE ?? '',
        textKey: 'markdown',
      };

      const response = await PineconeStore.fromDocuments(output, embeddings, dbConfig);
      // res.json({docId: documentId}); 
      res.json(response)
    } catch (error) {
      console.error('Error processing markdown uploading:', error);
      res.status(500).send('An error occurred while processing the file upload.');
    }
  }
);

/**
 * @method POST
 * @params role, message, embeddingModel, ranking
 * @middleware validations/searchEmbedding
 * @desc
 */
export const searchSimilarDocument = async (req: Request, res: Response) => {

  const role: string = req.body.role as string;
  const query: string = req.body.query as string;
  const ranking: number = (req.body.ranking as number) || 1;

  const client = new PineconeClient();
  await client.init({
    apiKey: process.env.PINECONE_API_KEY ?? '',
    environment: process.env.PINECONE_ENVIRONMENT ?? '',
  });

  const pineconeIndex = client.Index(process.env.PINECONE_INDEX ?? '');
  const vectorStore = await PineconeStore.fromExistingIndex(
    new OpenAIEmbeddings(),
    { 
      pineconeIndex: pineconeIndex,
      namespace: process.env.PINECONE_NAMESPACE ?? '',
      textKey: 'markdown'
    }
  );

  try {
    const results = await vectorStore.similaritySearch(query, ranking, {
      role: role,
    });
    const chat = new ChatOpenAI({ temperature: 0 });

    const response = await chat.call([
      new SystemChatMessage(
        `We have provided context information below:

        ---------------------/

        ${results[0].pageContent}
        ---------------------/

        Given this information, Please answer my question in the same language that I used to ask you.`
      ),
      new HumanChatMessage(query),
    ]);

    res.json(response);
  } catch (err) {
    console.error('Query Error: ' + err)
  }
};

