const prisma = new PrismaClient();

const AskQuestionPopup = ({ onClose, userId }) => {
    const [questionText, setQuestionText] = useState('');

    const handleQuestionChange = (e) => {
        setQuestionText(e.target.value);
    };

    const [validationMessage, setValidationMessage] = useState('');

    const openAIValidate = async (questionText) => {
        const OPENAI_API_KEY = process.env.NEXT_PUBLIC_OPENAI_API_KEY;
        const openai = new OpenAI(OPENAI_API_KEY);

        try {
            const response = await openai.createCompletion({
                model: "gpt-3.5-turbo",
                prompt: "Determine if the following text is appropriate: " + questionText,
                max_tokens: 60
            });

            return response.data.choices[0].text.trim();
        } catch (error) {
            console.error('Error with OpenAI validation:', error);
            return 'Error in validation';
        }
    };

    const handleAskPeers = async () => {
        const questionData = {
            userId: userId, 
            question: questionText,
        };

        const validationResponse = await openAIValidate(questionText);

        if (validationResponse === 'Appropriate') {
            try {
                const response = await fetch('/api/question/addQuestion', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(questionData),
                });

                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }

                const responseData = await response.json();
                console.log('Question added:', responseData);
                onClose();
            } catch (error) {
                console.error('Error submitting the question:', error);
            }
        } else {
            setValidationMessage('Your question is not appropriate.');
        }
    };

    return (
        <div className="popup-overlay">
            <div className="popup">
                <h1 className="popuptitle" style={{ color: '#f4f4f4', marginTop:'50px' }}>Ask a Question</h1>
                <textarea
                    className="question-input"
                    placeholder="Enter your question"
                    value={questionText}
                    onChange={handleQuestionChange}
                />
                {validationMessage && <div style={{color: 'red'}}>{validationMessage}</div>}
                <div className="popup-buttons">
                    <button className="ask-peers-button" onClick={handleAskPeers} data-text="Ask Your Peers"></button>
                    <button className="ask-ai-button">Ask AI</button>
                </div>
            </div>
        </div>
    );
}

export default AskQuestionPopup;

