        setGeneratingImg(true)

        const response = await fetch('http://localhost:8080/api/v1/dalle',{

          method:'POST',
          headers:{
            'Content-Type':'application/json',
            // "Authorization": "Bearer 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"
          },
          body:JSON.stringify({
            prompt,
          })


        })
        const data= await response.json()
        console.log("Received data:", data);
        handleDecals(type,`data:image/png;base64,${data.photo}`)


    }catch(error){
      alert(error)
    }finally{
      setGeneratingImg(false)
      setActiveEditorTab("")
    }
  }
  const handleDecals = (type,result) =>{
    if (!result) {
      console.error("Received undefined image data.");
      console.log("Complete response data:", result); // Log the entire response data for debugging
      return;
    }
    const decalType= DecalTypes[type]
    state[decalType.stateProperty]=result
    if(!activeFilterTab[decalType.filterTab]){
      handleActiveFilterTab(decalType.filterTab)
    }
  }

  const handleActiveFilterTab = (tabName)=>{
    switch(tabName){
      case "logoShirt":
        state.isLogoTexture = !activeFilterTab[tabName]
        break
      case "stylishShirt":
        state.isFilterTab = !activeFilterTab[tabName]
        break
      default:
        state.isFullTexture = false
        state.isLogoTexture = true  
    }
    // after setting the state activeFilterTab is updated
    setActiveFilterTab((prevState)=>{
      return{
        ...prevState,
        [tabName]:!prevState[tabName]
      }
    })
  }

  const readFile = (type)=>{
    reader(file)
    .then((result)=>{
      handleDecals(type,result)
      setActiveEditorTab("")
    })
  }

  return (
    <AnimatePresence>
      {!snap.intro && (
        <>
         <motion.div 
         key="custom"
         className='absolute top-0 left-0 z-10'
         {...slideAnimation('left')}>
          <div className='flex items-center min-h-screen'>
              <div className='editortabs-container tabs'>
                {EditorTabs.map((tab)=>(
                  <Tab
                  key={tab.name}
                  tab={tab}
                  handleClick={()=>{setActiveEditorTab(tab.name)}}/>
                ))}
                {generateTabContent()}
              </div>
          </div>

         </motion.div>
         <motion.div
         className='absolute z-10 top-5 right-5'
         {...fadeAnimation}>
          <CustomButton
          type="filled"
          title="Go Back"
          handleClick={()=>state.intro=true}
          customStyles='w-fit px-4 py-2.5 font-bold text-sm'
          />

         </motion.div>

         <motion.div className='filtertabs-container'
         {...slideAnimation('up')}>
           {FilterTabs.map((tab)=>(
                  <Tab
                  key={tab.name}
                  tab={tab}
                  isFilterTab
                  isActiveTab={activeFilterTab[tab.name]}
                  handleClick={()=>{handleActiveFilterTab(tab.name)}}/>
                ))}

         </motion.div>
        </>
      )}
    </AnimatePresence>
  )
}

