        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${API_KEY}`
        },
        body: JSON.stringify(APIBody)
      });

      const data = await response.json();
      console.log(data);

      if (data.choices && data.choices.length > 0) {
        const generatedText = data.choices[0].text.trim();
        setIsTextScriptAPI(generatedText);
      } else {
        setIsTextScriptAPI("No response from the API");
      }
    } catch (error) {
      console.error("Error:", error);
      setIsTextScriptAPI("API call failed");
    }
  }

  return (
    <Stack className="bgImage">
      <Home />
      <textarea
        onChange={(e) => setTextScript(e.target.value)}
        placeholder='Enter text'
        cols={75}
        rows={10}
      />
      <Button onClick={callOpenAIAPI}>
        SCAN
      </Button>
      {isTextScript !== "" && (
        <h3>This text {textScript} soccer text</h3>
      )}
    </Stack>
  );
};

export default App;

