And this is the function i used to fetch the pdf files so I can convert them to text
import * as pdfjs from "pdfjs-dist";

export async function getContent(src: string) {
  const doc = await pdfjs.getDocument(src).promise;
  const numPages = doc.numPages;
  const allTextContent = [];

  for (let pageNum = 1; pageNum <= numPages; pageNum++) {
    const page = await doc.getPage(pageNum);
    const pageTextContent = await page.getTextContent();

    allTextContent.push(pageTextContent);
  }

  return allTextContent;
}

export async function getItems(src: string) {
  const content = await getContent(src);
  const allItems = content.flatMap((pageContent) =>
    pageContent.items.map((textItem) => textItem.str || "")
  );
  return allItems;
}

