using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class FriendlyAI : MonoBehaviour
{
    public float moveSpeed = 3f;
    private Transform currentTarget;

    public float damageAmount = 2.0f;

    private void Start()
    {
        FindInitialTarget();
    }

    private void Update()
    {
        if (currentTarget != null)
        {
            Vector2 direction = currentTarget.position - transform.position;
            Vector2 newPosition = Vector2.MoveTowards(transform.position, currentTarget.position, moveSpeed * Time.deltaTime);
            transform.position = newPosition;
        }
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (other.CompareTag("Enemy"))
        {
            // Apply damage to the enemy's health
            HealthDamage healthDamage = other.GetComponent<HealthDamage>();

            if (healthDamage != null)
            {
                healthDamage.TakeDamage(Mathf.RoundToInt(damageAmount));
            }

            // Find a new target
            FindNewTarget();
        }
    }

    private void FindInitialTarget()
    {
        GameObject[] enemies = GameObject.FindGameObjectsWithTag("Enemy");
        if (enemies.Length > 0)
        {
            float closestDistance = Mathf.Infinity;
            foreach (GameObject enemy in enemies)
            {
                float distance = Vector3.Distance(transform.position, enemy.transform.position);
                if (distance < closestDistance)
                {
                    closestDistance = distance;
                    currentTarget = enemy.transform;
                }
            }
        }
        else
        {
            currentTarget = null;
        }
    }

    private void FindNewTarget()
    {
        GameObject[] enemies = GameObject.FindGameObjectsWithTag("Enemy");
        if (enemies.Length > 0)
        {
            int randomIndex = Random.Range(0, enemies.Length);
            currentTarget = enemies[randomIndex].transform; 

            Debug.Log("New Target Chosen");
        }
        else
        {
            currentTarget = null; // No enemies found
        }
    }
}


