function App() {
  const [prompt, setPrompt] = useState("");
  const [message, setMessage] = useState("");
  const requestOption = {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ prompt: prompt })
  }
  const fetchdata = () => {
    fetch("http://localhost:5000/bard", requestOption)
