I have a dataframe with columns containing words (1), their definitions (2), common synonyms (3) and English translation (4). Most of these are filled, however, I was looking for a way to input the words (of incomplete rows) and request corresponding output and fill the table via Open's text engines via API. I have run across a few problems.
So far, I have managed to fill the columns but I get odd returns, such as repeating the request and repeating the input word. This was done using the following code (I have assigned my API key to api_key):
library(httr)
library(reticulate)

generate_completion <- function(prompt) {
  response <- httr::POST(
    url = "https://api.openai.com/v1/engines/davinci/completions",
    httr::add_headers(`Authorization` = paste("Bearer", api_key)),
    httr::content_type("application/json"),
    body = list(
      prompt = prompt,
      max_tokens = 60,
      temperature = 0.7,
      n = 1
    ),
    encode = "json"
  )

  response <- httr::content(response)
  return(response$choices[[1]]$text)
}

# function for filling missing values
fill_missing_values <- function(row) {
  if (is.na(row$Def)) {
    prompt <- paste("What is the definition of", row$Swe, "?")
    row$Def <- generate_completion(prompt)
  }

  if (is.na(row$Syn)) {
    prompt <- paste("What are two synonyms for", row$Swe, "?")
    row$Syn <- generate_completion(prompt)
  }

  if (is.na(row$Eng)) {
    prompt <- paste("What is the english translation for", row$Swe, "?")
    row$Eng <- generate_completion(prompt)
  }

  return(row)
}

