function getEmailText(messageId) {
  var accessToken = ScriptApp.getOAuthToken();
  var apiUrl = 'https://www.googleapis.com/gmail/v1/users/me/messages/' + messageId + '?format=raw';

  try {
    // Fetch the email message in raw format
    var response = UrlFetchApp.fetch(apiUrl, {
      headers: {
        Authorization: 'Bearer ' + accessToken
      }
    });

    // Parse the JSON response
    var message = JSON.parse(response.getContentText());

    // Get the raw encoded message
    var encodedBody = message.raw;

    // Try different decoding methods
    var decodedText = decodeEmailBody(encodedBody);

    // Return the decoded text
    return decodedText;
  } catch (error) {
    console.error('Error decoding email message:', error);
    return 'Error decoding email message: ' + error.message;
  }
}

function decodeEmailBody(encodedBody) {
  try {
    // Base64 decode
    var decodedBody = Utilities.base64Decode(encodedBody);
    var emailText = Utilities.newBlob(decodedBody).getDataAsString();

    // Return the decoded text if successful
    if (emailText) {
      return emailText;
    }

    // Try UTF-8 decoding
    var emailTextUtf8 = Utilities.newBlob(emailText, 'UTF-8').getDataAsString();
    if (emailTextUtf8) {
      return emailTextUtf8;
    }

    // Try quoted-printable decoding
    var decodedTextQP = decodeQuotedPrintable(emailText);
    if (decodedTextQP) {
      return decodedTextQP;
    }
  } catch (error) {
    console.error('Error decoding email message:', error);
    return 'Error decoding email message: ' + error.message;
  }

  return 'Unable to decode email message with available methods.';
}

function decodeQuotedPrintable(emailText) {
  try {
    // Decode using quoted-printable decoding
    return Utilities.newBlob(emailText, 'quoted-printable').getDataAsString();
  } catch (error) {
    console.error('Error decoding quoted-printable message:', error);
    return null;
  }
}

function getEmailHeaders(messageId) {
  var accessToken = ScriptApp.getOAuthToken();
  var apiUrl = 'https://www.googleapis.com/gmail/v1/users/me/messages/' + messageId + '?format=full';

  try {
    var response = UrlFetchApp.fetch(apiUrl, {
      headers: {
        Authorization: 'Bearer ' + accessToken
      }
    });

    // Parse the JSON response
    var messageData = JSON.parse(response.getContentText());

    // Extract the headers from the message data
    var headers = messageData.payload.headers;

    // Return the headers
    return headers;
  } catch (error) {
    console.error('Error fetching email headers:', error);
    return 'Error fetching email headers: ' + error.message;
  }
}

async function sendToChatGPT(emailText) {
  // OpenAI ChatGPT API endpoint
  const url = 'https://api.openai.com/v1/chat/completions';

  // Headers including the API key
  const headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer MY KEY' // Replace 'YOUR_API_KEY' with your actual OpenAI API key
  };

  // Request body for OpenAI ChatGPT API
  const body = JSON.stringify({
    model: 'gpt-3.5-turbo',
    messages: [
      {
        role: 'user',
        content: 'Is this mail a scam?' + '
' + emailText
      }
    ],
    temperature: 0.9,
    max_tokens: 256,
    top_p: 0.9,
    frequency_penalty: 0.0,
    presence_penalty: 0.0
  });

  try {
    // Fetch the response using UrlFetchApp.fetch
    const response = UrlFetchApp.fetch(url, {
      method: 'post',
      headers: headers,
      payload: body,
      muteHttpExceptions: true // Optional: prevents exceptions from being thrown for HTTP errors
    });

    // Parse the JSON response
    const result = JSON.parse(response.getContentText());

    // Extract the text from the response object
    if (result.choices && result.choices[0] && result.choices[0].message) {
      const text = result.choices[0].message.content;
      return text;
    } else {
      return 'Unexpected response structure from API.';
    }
  } catch (error) {
    console.error('Error fetching response from API:', error);
    return 'Error fetching response from API: ' + error.message;
  }
}

