And here's how api calling is setup:
export const chatapi = async (question, deviceId, callback, onSuccess) => {
  try {
    let data = JSON.stringify({
      user: question,
    });

    let es = new EventSource(`${BASE_URL}/v1/add_chat`, {
      method: "post",
      headers: {
        deviceid: deviceId,
        "Content-Type": "application/json",
      },
      body: data,
    });

    es.addEventListener("open", (event) => {
      console.log("open ===>>>", event.type);
    });

    es.addEventListener("message", (event) => {
      // console.log("message event  ==>>", event.data);
      if (!event) {
        console.log("!event");
        es.close();
      } else {
        const data = JSON.parse(event.data);
        // console.log("New message event data:", data);
        // console.log('event.data?.event === "close" ==>>', data?.event);
        if (data?.event === "close") {
          es.close();
        } else if (data?.user) {
          onSuccess(data?.user);
        } else {
          callback(data);
        }
      }
    });

    es.addEventListener("error", (event) => {
      if (event.type === "error") {
        console.error("Connection error:", event.message);
        es.close();
      } else if (event.type === "exception") {
        console.error("Error:", event.message, event.error);
        es.close();
      }
    });

    es.addEventListener("close", (event) => {
      console.log("Close SSE connection.", event);
      setTimeout(() => {
        es.close();
        es.removeAllEventListeners();
      }, 1000);
    });
  } catch (error) {
    console.log("chatapi error ==>>", error);
  }
};

export const visionApi = async (
  question,
  attachment,
  deviceId,
  callback,
  onSuccess
) => {
  try {
    const ATTACHMENT_TYPES = {
      img: "image",
      pdf: "pdf",
    };
    console.log("vision api attachment ==<>>>>", attachment);
    let fileUri = Platform.select({
      ios: attachment.uri.replace("file://", ""),
      android: attachment.uri,
    });

    let data = new FormData();
    data.append("file", {
      name: attachment.type.includes(ATTACHMENT_TYPES.pdf)
        ? attachment.name
        : attachment.fileName,
      type: attachment.type,
      uri: fileUri,
    });
    data.append("prompt", question);

    let es = new EventSource(`${BASE_URL}/v1/image_editing`, {
      method: "post",
      maxBodyLength: Infinity,
      headers: {
        deviceid: deviceId,
        "Content-Type": "multipart/form-data",
        "Cache-Control": "no-cache",
        Connection: "keep-alive",
      },
      body: data,
    });

    es.addEventListener("open", (event) => {
      console.log("open ===>>>", event.type);
    });

    es.addEventListener("message", (event) => {
      if (!event) {
        console.log("!event");
        es.close();
      } else {
        const data = JSON.parse(event.data);
        // console.log("New message event data:", data);
        // console.log('event.data?.event === "close" ==>>', data?.event);
        if (data?.event === "close") {
          es.close();
        } else if (data?.user) {
          onSuccess(data?.user);
        } else {
          // console.log("message event  ==>>", event.data);
          callback(data);
        }
      }
    });

    es.addEventListener("error", (event) => {
      if (event.type === "error") {
        console.error("Connection error:", event.message);
        es.close();
      } else if (event.type === "exception") {
        console.error("Error:", event.message, event.error);
        es.close();
      }
    });

    es.addEventListener("close", (event) => {
      console.log("Close SSE connection.", event);
      setTimeout(() => {
        es.close();
        es.removeAllEventListeners();
      }, 1000);
    });
  } catch (error) {
    console.log("vision error ==>>", error);
  }
};

