import Foundation

class GPTManager {
    private let apiKey = "MY KEY HERE"
    private let session = URLSession.shared
    private let baseUrl = "https://api.openai.com/v1/engines/YOUR_ENGINE_ID/completions"

    func getResponse(prompt: String, completion: @escaping (String?) -> Void) {
        guard let url = URL(string: baseUrl) else {
            completion(nil)
            return
        }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.addValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
        request.addValue("application/json", forHTTPHeaderField: "Content-Type")

        let body: [String: Any] = [
            "prompt": prompt,
            "max_tokens": 100
        ]

        request.httpBody = try? JSONSerialization.data(withJSONObject: body, options: [])

        let task = session.dataTask(with: request) { data, response, error in
            guard let data = data, error == nil else {
                completion(nil)
                return
            }

            if let responseDictionary = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: Any],
               let text = responseDictionary["choices"] as? [[String: Any]],
               let firstChoice = text.first,
               let finalText = firstChoice["text"] as? String {
                DispatchQueue.main.async {
                    completion(finalText.trimmingCharacters(in: .whitespacesAndNewlines))
                }
            } else {
                completion(nil)
            }
        }

        task.resume()
    }
}

