import React, { useState, useEffect, Suspense } from "react";
import "./App.css";
import axios from "axios";

function DetectedTextComponent({ base64Image }) {
  const [detectedText, setDetectedText] = useState("");
  const [gptResponse, setGptResponse] = useState("");

  useEffect(() => {
    const detectText = async () => {
      if (!base64Image) return;
      try {
        const response = await axios.post(
          "http://localhost:3001/api/detect-text",
          { image: base64Image }
        );
        setDetectedText(response.data.text || "");
      } catch (error) {
        console.error("Text detection failed:", error);
        setDetectedText(`Error: ${error.message}`);
      }
    };
    detectText();
  }, [base64Image]);

  useEffect(() => {
    const getGptResponse = async () => {
      if (!detectedText) return;
      try {
        const response = await axios.post(
          "http://localhost:3001/api/ask-chatgpt",
          { question: detectedText }
        );
        setGptResponse(response.data.answer || "");
      } catch (error) {
        console.error("Error asking ChatGPT:", error);
        setGptResponse("Error getting response from ChatGPT");
      }
    };
    getGptResponse();
  }, [detectedText]);

  return (
    <div>
      <p>Detected Text: {detectedText}</p>
      <p>ChatGPT Response: {gptResponse}</p>
    </div>
  );
}

