backend
require("dotenv").config();
const express = require("express");
const bodyParser = require("body-parser");
const vision = require("@google-cloud/vision");
const cors = require("cors");
const axios = require("axios");
const app = express();
const port = 3001;

const endpoint = process.env.CHATGPT_ENDPOINT;
axios
  .post(endpoint, "https://api.openai.com/v1/chat/completions")
  .then((response) => {
    console.log(response.data);
  })
  .catch((error) => {
    console.error("Error asking ChatGPT:", error);
  });

const client = new vision.ImageAnnotatorClient({
  projectId: process.env.GCP_PROJECT_ID,
  keyFilename: process.env.GCP_KEY_FILENAME,
});
app.use(cors());
app.use(bodyParser.json({ limit: "10mb" }));
app.use(bodyParser.urlencoded({ extended: true }));

app.post("/api/detect-text", async (req, res) => {
  try {
    console.log("Received image for text detection.");
    if (!req.body.image || typeof req.body.image !== "string") {
      return res.status(400).json({ error: "Invalid image data" });
    }
    const image = req.body.image?.split(",")[1];
    if (!image) return res.status(400).json({ error: "Invalid image format" });

    const [result] = await client.textDetection({ image: { content: image } });
    const text = result.textAnnotations[0]?.description.trim() || "";
    res.json({ text });
  } catch (error) {
    console.error("Error detecting text:", error);
    res.status(500).json({ error: error.message });
  }
});

app.post("/api/ask-chatgpt", async (req, res) => {
  try {
    const question = req.body.question || "";
    const response = await axios.post(
      process.env.CHATGPT_ENDPOINT,
      {
        engine: "gpt-3.5-turbo",
        prompt: question,
        max_tokens: 50,
        temperature: 0.2,
      },
      {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${process.env.CHATGPT_API_KEY}`,
        },
      }
    );
    res.json({ answer: response.data.answer });
