                ForEach($models, id: \.self) { $string in
                    Text(string)
                }
                Spacer()
                HStack {
                    TextField("type here ...", text: $text)
                    Button("Send") {
                        send()
                    }
                }
            }
            .onAppear {
                viewModel.setup()
            }
            .padding()
    }

    private func send() {
        guard !text.trimmingCharacters(in: .whitespaces).isEmpty else { return }
        models.append("Me: \(text)")
